<?php
declare(strict_types=1);require dirname(__DIR__).'/workflow-core.php';trackingHeaders();if(($_SERVER['REMOTE_USER']??'')!=='aor-project-admin'){http_response_code(403);exit('Project admin is locked.');}
$type=(string)($_GET['type']??'projects');if(!in_array($type,['projects','invoices','activity'],true)){http_response_code(422);exit('Unknown export.');}$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');foreach([$from,$to] as $date)if($date!==''&&!DateTimeImmutable::createFromFormat('!Y-m-d',$date)){http_response_code(422);exit('Invalid date range.');}
// Activity can be exported for one project (from its workflow page) or for every project.
$project=is_string($_GET['project']??null)?$_GET['project']:'';$event=is_string($_GET['event']??null)?preg_replace('/[^a-z_]/','',$_GET['event']):'';$records=[];
trackingEnsureReferences();
if($type==='activity'){try{$records=$project!==''?[$project=>trackingRead(trackingId($project))]:trackingRecords();}catch(Throwable){http_response_code(422);exit('Unknown project.');}}
$name='aor-'.$type.($type==='activity'&&$project!==''?'-'.preg_replace('/[^A-Za-z0-9-]/','',(string)($records[$project]['reference']??substr($project,0,8))):'').($event!==''?'-'.str_replace('_','-',$event):'').'-'.gmdate('Y-m-d');
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$name.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
// A cell starting with = + - @ would run as a formula in Excel or Sheets; client text must stay plain text.
$row=static function($out,array $values):void{fputcsv($out,array_map(static fn($v):string=>preg_match('/\A[=+\-@\t\r]/',(string)$v)?"'".$v:(string)$v,$values),',','"','\\');};
$within=static function(string $date)use($from,$to):bool{$day=substr($date,0,10);return($from===''||$day>=$from)&&($to===''||$day<=$to);};
if($type==='projects'){$row($out,['project_ref','title','stage','client_name','client_email','created_at','updated_at','completed','internal_id']);foreach(trackingRecords() as $id=>$record)if($within((string)($record['created_at']??'')))$row($out,[$record['reference']??'',$record['title']??'',$record['stage']??'',$record['client_name']??'',$record['client_email']??'',$record['created_at']??'',$record['updated_at']??'',($record['completed']??false)?'yes':'no',$id]);}
elseif($type==='activity'){$local=static function(string $at):string{try{return(new DateTimeImmutable($at))->setTimezone(new DateTimeZone('Asia/Riyadh'))->format('Y-m-d H:i');}catch(Throwable){return $at;}};
$row($out,['date_riyadh','date_utc','project_ref','project_title','event','detail']);
foreach($records as $id=>$record)foreach(array_reverse(is_array($record['activity']??null)?$record['activity']:[]) as $entry){$at=(string)($entry['at']??'');if(!$within($at)||($event!==''&&($entry['event']??'')!==$event))continue;$row($out,[$local($at),$at,$record['reference']??'',$record['title']??'',ucwords(str_replace('_',' ',(string)($entry['event']??''))),(string)($entry['detail']??'')]);}}
else{$row($out,['project_ref','project_title','invoice_number','type','issue_date','due_date','currency','amount_due','status','paid_at']);foreach(trackingRecords() as $id=>$raw){$record=workflowProject($raw);foreach($record['invoices'] as $invoice)if($within($invoice['issue_date']))$row($out,[$record['reference']??'',$record['title'],$invoice['number'],$invoice['type'],$invoice['issue_date'],$invoice['due_date'],$record['currency'],number_format($invoice['amount_due_cents']/100,2,'.',''),$invoice['status'],$invoice['paid_at']]);}}fclose($out);
